// Recoverable card removal. Generated files move to the project's _trash folder.
const cardTrashSvg='<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M4 7h16M9 7V4h6v3M6 7l1 14h10l1-14M10 11v6m4-6v6"/></svg>';
function cardTrashButton(label,action){const button=document.createElement('button');button.type='button';button.className='card-trash';button.title=label;button.setAttribute('aria-label',label);button.innerHTML=cardTrashSvg;button.onpointerdown=e=>e.stopPropagation();button.ondragstart=e=>e.preventDefault();button.onclick=e=>{e.preventDefault();e.stopPropagation();action();};return button;}
function cardArchive(kind,item,extra={}){state.cardTrash||=[];state.cardTrash.push({kind,item:copyVersionData(item),deletedAt:new Date().toISOString(),...extra});}
function cardDeleteAsset(assetIdToDelete){const index=state.assets.findIndex(a=>a.id===assetIdToDelete);if(index<0)return;const asset=state.assets[index];cardArchive('asset',asset);state.assets.splice(index,1);for(const scene of state.scenes)for(const cut of scene.cuts)if(cut.referenceAssetIds)cut.referenceAssetIds=cut.referenceAssetIds.filter(id=>id!==assetIdToDelete);if(assetId===assetIdToDelete)assetId=null;save();renderAssets();renderStory();toast('어셋을 프로젝트 휴지통으로 옮겼습니다.');}
function cardDeleteCut(cutIdToDelete){const scene=state.scenes.find(s=>s.cuts.some(c=>c.id===cutIdToDelete));if(!scene)return;const index=scene.cuts.findIndex(c=>c.id===cutIdToDelete);cardArchive('cut',scene.cuts[index],{sceneId:scene.id,index});scene.cuts.splice(index,1);if(cutId===cutIdToDelete)cutId=scene.cuts[Math.min(index,scene.cuts.length-1)]?.id||null;save();render();toast('컷을 프로젝트 휴지통으로 옮겼습니다.');}
function cardDeleteMood(moodIdToDelete){const items=state.moodReferences||[],index=items.findIndex(item=>item.id===moodIdToDelete);if(index<0)return;cardArchive('mood',items[index]);items.splice(index,1);if(moodId===moodIdToDelete)moodId=null;save();renderAssets();toast('무드 레퍼런스를 프로젝트 휴지통으로 옮겼습니다.');}
function cardHiddenMedia(){return new Set(state.deletedMediaPaths||[]);}
async function cardDeleteOutput(requestId,mediaPath){const request=(state.generationRequests||[]).find(r=>r.id===requestId);if(!request||cardHiddenMedia().has(mediaPath))return;const response=await fetch('/api/project-media-trash',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({projectId:state.projectId,mediaPath})});const result=await response.json();if(!response.ok)throw Error(result.error||'미디어 삭제 실패');state.deletedMediaPaths||=[];state.deletedMediaPaths.push(mediaPath);state.mediaTrash||=[];state.mediaTrash.push({requestId,mediaPath,trashPath:result.trashPath,deletedAt:new Date().toISOString()});
  const detach=entity=>{if(entity.image===mediaPath)entity.image='';if(entity.video===mediaPath)entity.video='';if(entity.videoPath===mediaPath)entity.videoPath='';if(entity.references)entity.references=entity.references.filter(ref=>ref.path!==mediaPath);};
  for(const asset of state.assets){detach(asset);for(const version of asset.versions||[])detach(version.data);}
  for(const scene of state.scenes)for(const cut of scene.cuts){detach(cut);for(const version of cut.versions||[])detach(version.data);}
  state.studioUploads=(state.studioUploads||[]).filter(item=>item.path!==mediaPath);state.moodReferences=(state.moodReferences||[]).filter(item=>item.path!==mediaPath);
  if(state.studioDraft?.references)state.studioDraft.references=state.studioDraft.references.filter(ref=>ref.path!==mediaPath);
  for(const clip of state.timeline?.clips||[]){if(clip.video===mediaPath)clip.video='';if(clip.image===mediaPath)clip.image='';}
  for(const track of state.timeline?.videoTracks||[])track.clips=track.clips.filter(clip=>clip.video!==mediaPath);
  if(state.timeline?.videoTracks)state.timeline.videoTracks=state.timeline.videoTracks.filter(track=>track.clips.length);
  const job=generationJobs.filter(job=>job.projectId===state.projectId&&job.requestId===requestId).at(-1);if(job?.outputs?.every(output=>cardHiddenMedia().has(output.path)))request.deleted=true;
  if(typeof tbItems!=='undefined'){tbItems=tbItems.filter(item=>item.path!==mediaPath);tbRender();}
  if(typeof studioLibraryChoices!=='undefined'){studioLibraryChoices=studioLibraryChoices.filter(item=>item.path!==mediaPath);studioLibrarySelected.delete(mediaPath);if($('#studioLibraryDialog')?.open)renderStudioLibrary();}
  save();await flush();renderStudioResults.signature=null;renderQueue.signature=null;renderStudioResults();renderQueue();renderAssets();renderGenerationJobs();if(activeTab==='timeline')renderTimeline();toast('생성 결과를 프로젝트 휴지통으로 옮겼습니다.');
}
const cardQueueEntriesBefore=queueEntries;queueEntries=function(){const hidden=cardHiddenMedia();return cardQueueEntriesBefore().filter(entry=>!entry.request.deleted).map(entry=>({...entry,job:entry.job?{...entry.job,outputs:(entry.job.outputs||[]).filter(output=>!hidden.has(output.path))}:entry.job}));};
const cardRenderAssetsBefore=renderAssets;renderAssets=function(){cardRenderAssetsBefore();if(assetType==='mood'){for(const card of document.querySelectorAll('#assetGrid .mood-card[data-mood]'))card.append(cardTrashButton('무드 레퍼런스 삭제',()=>cardDeleteMood(card.dataset.mood)));return;}for(const card of document.querySelectorAll('#assetGrid [data-asset]')){const wrapper=document.createElement('div');wrapper.className='asset-trash-wrap';card.replaceWith(wrapper);wrapper.append(card,cardTrashButton('어셋 삭제',()=>cardDeleteAsset(card.dataset.asset)));}};
const cardRenderBoardBefore=renderBoard;renderBoard=function(){cardRenderBoardBefore();for(const card of document.querySelectorAll('#board [data-cut]'))card.querySelector('.cut-top')?.append(cardTrashButton('컷 삭제',()=>cardDeleteCut(card.dataset.cut)));};
const cardRenderStudioBefore=renderStudioResults;renderStudioResults=function(){cardRenderStudioBefore();for(const card of document.querySelectorAll('#studioResults .studio-card[data-studio-key]')){if(card.querySelector('.card-trash'))continue;const [requestId,mediaPath]=card.dataset.studioKey.split(':');if(!mediaPath||mediaPath==='pending')continue;card.querySelector('.cut-top')?.append(cardTrashButton('생성 결과 삭제',async()=>{try{await cardDeleteOutput(requestId,mediaPath);}catch(error){toast(error.message);}}));}};
